1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * The owner-email rule for the create pipeline's {@link ValidateOwnerFields}: email is optional, but
8	 * when supplied it must be a syntactically valid address, and it is lower-cased before being stored
9	 * so it is returned lower-cased.
10	 *
11	 * <p>Mirrors {@link OwnerTelephone}. As with telephone, only the create path validates and
12	 * normalizes programmatically; the update path ({@link ValidateOwner}) leans on the
13	 * bean-validation {@code @Email} / {@code @Size} constraints on the generated DTO instead, so this
14	 * helper is intentionally not referenced there.
15	 */
16	final class OwnerEmail {
17	
18	    /** Syntactic check: a non-empty local part, an {@code @}, and a dotted domain, no whitespace. */
19	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
20	
21	    private OwnerEmail() {
22	    }
23	
24	    static boolean isValid(String value) {
25	        return value != null && EMAIL.matcher(value).matches();
26	    }
27	
28	    static String normalize(String value) {
29	        return value == null ? null : value.toLowerCase(Locale.ROOT);
30	    }
31	}
