1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	/**
6	 * Thrown by {@link ValidateOwnerFields} when a create request is missing or blank in one or more
7	 * required owner fields. Handled globally by {@code OwnerFieldsInvalidExceptionHandler}, which
8	 * responds 400 with a JSON body listing the offending field names.
9	 */
10	public class OwnerFieldsInvalidException extends Exception {
11	
12	    private final List<String> errors;
13	
14	    public OwnerFieldsInvalidException(List<String> errors) {
15	        super("Missing or blank owner fields: " + errors);
16	        this.errors = List.copyOf(errors);
17	    }
18	
19	    public List<String> getErrors() {
20	        return errors;
21	    }
22	}
