3	import java.util.Map;
4	
5	import net.officefloor.plugin.section.clazz.Parameter;
6	import net.officefloor.web.ObjectResponse;
7	import org.springframework.http.HttpStatus;
8	import org.springframework.http.ResponseEntity;
9	
10	/**
11	 * Responds 400 with a JSON body whose {@code errors} array lists the name of each owner field that
12	 * was missing or blank.
13	 */
14	public class OwnerFieldsInvalidExceptionHandler {
15	
16	    public void handle(@Parameter OwnerFieldsInvalidException ex,
17	            ObjectResponse<ResponseEntity<Map<String, Object>>> response) {
18	        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST)
19	                .body(Map.of("errors", ex.getErrors())));
20	    }
21	}
