3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.model.OwnerRegion;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.web.bind.annotation.RequestBody;
11	
12	/**
13	 * Rejects a create request that is missing or blank in any required owner field.
14	 *
15	 * <p>Runs first in the {@code POST /api/owners} pipeline. It binds the body once (this is the only
16	 * step that reads {@code @RequestBody}) and republishes it for {@link BuildOwner}. Each of
17	 * firstName, lastName, address, city and telephone must be present and non-blank; any that are not
18	 * are collected and reported together via {@link OwnerFieldsInvalidException}. A supplied
19	 * registrationDate must not be later than the server's current date.
20	 *
21	 * <p>The telephone is converted to E.164 form (see {@link OwnerTelephone#toE164}). The E.164 value
22	 * replaces the submitted one on the republished body, so it is what gets stored and returned. A
23	 * number that cannot form valid E.164 is rejected as an invalid {@code telephone}.
24	 */
25	public class ValidateOwnerFields {
26	
27	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
28	            throws OwnerFieldsInvalidException {
29	        List<String> errors = new ArrayList<>();
30	        if (isBlank(request.getFirstName())) {
31	            errors.add("firstName");
32	        }
33	        if (isBlank(request.getLastName())) {
34	            errors.add("lastName");
35	        }
36	        // The address is normalized (whitespace collapsed, upper-cased, abbreviations expanded)
37	        // before the required-field check, so an address that is blank only after normalization is
38	        // rejected; the normalized value replaces the submitted one, so it is what gets stored,
39	        // returned and compared for household identity.
40	        String address = OwnerAddress.normalize(request.getAddress());
41	        if (address.isEmpty()) {
42	            errors.add("address");
43	        }
44	        else {
45	            request.setAddress(address);
46	        }
47	        if (isBlank(request.getCity())) {
48	            errors.add("city");
49	        }
50	        if (isBlank(request.getTelephone())) {
51	            errors.add("telephone");
52	        }
53	        else {
54	            String telephone = OwnerTelephone.toE164(request.getTelephone());
55	            if (telephone == null) {
56	                errors.add("telephone");
57	            }
58	            else {
59	                request.setTelephone(telephone);
